function wireQuickAccount(names){
 $('quickAccountRole').value='GUARD';$('quickGuardMethod').value='password';let lastUsername='',lastPassword='';
 const suggest=()=>{if(!$('quickGuardPassword').value||$('quickGuardPassword').value===lastPassword){lastPassword=$('quickAccountRole').value==='GUARD'?usernameTemporaryPassword($('quickGuardUsername').value):generateTemporaryPassword();$('quickGuardPassword').value=lastPassword;}};
 const method=()=>{const guard=$('quickAccountRole').value==='GUARD';if(!guard)$('quickGuardMethod').value='password';const phone=guard&&$('quickGuardMethod').value==='phone';$('quickGuardMethodLabel').hidden=!guard;$('quickDisplayNameLabel').hidden=guard;$('quickDisplayName').required=!guard;$('quickGuardName').required=guard;$('quickGuardPhoneFields').hidden=!phone;$('quickGuardPasswordFields').hidden=phone;$('quickGuardCodeButton').hidden=!phone;$('saveQuickGuard').hidden=phone;$('quickGuardPhone').required=phone;$('quickGuardPhone').disabled=!phone;$('quickGuardUsername').disabled=$('quickGuardPassword').disabled=phone;$('quickDisplayName').disabled=guard;$('quickGuardUsername').required=$('quickGuardPassword').required=!phone;$('quickGuardPassword').minLength=guard?4:10;$('quickGuardGeneratePassword').textContent=guard?'Use username + 1':'Generate temporary password';$('quickPasswordHint').textContent=guard?'Temporary password fills as username + 1. The user must choose a new password at first sign-in.':'Use at least 10 characters. The user must choose a new password at first sign-in.';};
 $('quickGuardMethod').onchange=method;$('quickAccountRole').onchange=()=>{method();lastPassword=$('quickAccountRole').value==='GUARD'?usernameTemporaryPassword($('quickGuardUsername').value):generateTemporaryPassword();$('quickGuardPassword').value=lastPassword;};method();
 $('quickGuardName').onchange=()=>{if(!$('quickGuardUsername').value||$('quickGuardUsername').value===lastUsername){lastUsername=$('quickGuardName').value.toLowerCase().replace(/[^a-z0-9]+/g,'.').replace(/^\.|\.$/g,'');$('quickGuardUsername').value=lastUsername;}suggest();};$('quickGuardUsername').oninput=suggest;
 wirePasswordControls('quickGuardPassword','quickGuardGeneratePassword','quickGuardShowPassword','quickGuardCopyPassword',()=>{lastPassword=$('quickAccountRole').value==='GUARD'?usernameTemporaryPassword($('quickGuardUsername').value):generateTemporaryPassword();return lastPassword;});
 wireLoginDetailsCopy('quickGuardCopyPassword',()=>$('quickGuardUsername').value,()=>$('quickGuardPassword').value,'quickLoginDetails');
 const create=generate=>run(async()=>{const role=$('quickAccountRole').value,guard=role==='GUARD',guardName=$('quickGuardName').value,name=guard?guardName:$('quickDisplayName').value.trim(),phone=$('quickGuardPhone').value,withPassword=!guard||$('quickGuardMethod').value!=='phone';if(!name)throw Error(guard?'Choose a guard.':'Enter a name.');const username=$('quickGuardUsername').value.trim().toLowerCase(),password=$('quickGuardPassword').value;if(withPassword&&(!username||!password))throw Error('Enter a username and temporary password.');if(!withPassword&&!phone.trim())throw Error('Enter the guard’s phone number.');
 const result=await api('/api/users',{method:'POST',body:JSON.stringify({role,guardName,name,...(withPassword?{username,password}:{phone,generate})})});await refreshStaffAccess();if(withPassword){await accounts();$('managementStatus').textContent='Account created. Username: '+username+'. The user must change their temporary password at first sign-in.';}else{accessPanel({id:result.id,name,guardName,role:'GUARD',phone},names);if(result.code){$('phoneCodeResult').hidden=false;$('generatedPhoneCode').value=result.code;$('managementStatus').textContent='Account created. Share this code privately; it does not expire and works once.';}else $('managementStatus').textContent='Guard account created. Generate a temporary code when they are ready to sign in.';}});
 $('quickGuardForm').onsubmit=e=>{e.preventDefault();return create($('quickGuardMethod').value==='phone');};$('saveQuickGuard').onclick=()=>{if($('quickGuardForm').reportValidity?.()===false)return;return create(false);};
}
