async function manualSwitchPanel(){await savesFinished();const w=window.scheduleApp.getWorkspace();panel('Manual shift switch','<p>Exchange two assigned shifts directly. This is a management action and takes effect immediately when applied. The original schedule is backed up.</p><form id="manualSwitchForm"><label>Week<select id="manualSwitchWeek">'+Object.keys(w.weeks).sort().reverse().map(end=>'<option value="'+end+'">W-E '+date(end)+'</option>').join('')+'</select></label><div class="subfields"><label>First shift<select id="manualSwitchFrom" required></select></label><label>Second shift<select id="manualSwitchTo" required></select></label></div><p id="manualSwitchSummary" class="notice"></p><label>Reason / note<input id="manualSwitchNote" required maxlength="500" placeholder="Switch arranged by management"></label><button class="primary" type="submit">Apply manual switch</button><button id="cancelManualSwitch" type="button">Cancel</button></form>');$('manualSwitchWeek').value=w.activeWeek;let shifts=[];const summary=()=>{const a=shifts.find(s=>s.key===$('manualSwitchFrom').value),b=shifts.find(s=>s.key===$('manualSwitchTo').value);$('manualSwitchSummary').textContent=a&&b?a.guard+' will take '+b.post+' ('+DAYS[b.day]+'), and '+b.guard+' will take '+a.post+' ('+DAYS[a.day]+').':'Choose two different guards’ shifts.';};const load=async()=>{const result=await api('/api/manual-switch/options?week='+encodeURIComponent($('manualSwitchWeek').value));shifts=result.shifts;const options='<option value="">Choose shift</option>'+shifts.map(s=>'<option value="'+esc(s.key)+'">'+esc(s.guard)+' · '+DAYS[s.day]+' · '+esc(s.post)+' · '+time(s.start)+'–'+time(s.end)+'</option>').join('');$('manualSwitchFrom').innerHTML=$('manualSwitchTo').innerHTML=options;summary();};$('manualSwitchWeek').onchange=()=>run(load);$('manualSwitchFrom').onchange=$('manualSwitchTo').onchange=summary;$('cancelManualSwitch').onclick=()=>$('managementDialog').close();$('manualSwitchForm').onsubmit=e=>{e.preventDefault();run(async()=>{await savesFinished();await api('/api/manual-switch',{method:'POST',body:JSON.stringify({week:$('manualSwitchWeek').value,fromKey:$('manualSwitchFrom').value,toKey:$('manualSwitchTo').value,note:$('manualSwitchNote').value,revision:window.__BOOT.revision})});location.reload();});};await load();}

let masterOptionsVersion=0;
async function loadMasterOptions(){
 const version=++masterOptionsVersion,selectedFrom=$('futureFrom').value,selectedTo=$('futureTo').value; $('futureFrom').innerHTML='';$('futureTo').innerHTML='';
 const data=await api('/api/master-switch-options?week='+encodeURIComponent($('futureWeek').value)+'&partner='+encodeURIComponent($('futurePartner').value));if(version!==masterOptionsVersion)return;
 const options=items=>'<option value="">Choose shift</option>'+items.map(shift=>'<option value="'+esc(shift.key)+'">'+requestShift(shift,data.week)+'</option>').join('');
 $('futureFrom').innerHTML=options(data.mine);$('futureTo').innerHTML=options(data.theirs);if(data.mine.some(s=>s.key===selectedFrom))$('futureFrom').value=selectedFrom;if(data.theirs.some(s=>s.key===selectedTo))$('futureTo').value=selectedTo;
}
$('futureWeek').onchange=$('futurePartner').onchange=()=>run(loadMasterOptions,'requestError');
function submissionCards(items,management=false){return items.map(r=>{
 const p=r.payload,kind=r.kind==='FUTURE_SWITCH',status=r.effectiveStatus||r.status;
 const labels={PENDING:kind?(r.partner_status==='APPROVED'?'Waiting for manager':'Waiting for other guard'):'Waiting for manager',WAITING_SCHEDULE:'Approved — waiting for schedule',APPLIED:'Applied to schedule',NEEDS_REVIEW:'Assignments changed — manager review needed',APPROVED:kind?'Approved — needs manager review':'Approved — added to payroll',DENIED:'Declined',CANCELLED:'Cancelled'};
 let actions=!kind&&management?'<button data-open-missing="'+esc(r.id)+'">Review schedule & payment history</button>':'';if(r.status==='PENDING'){
  if(r.partner_user_id===user.id&&r.partner_status==='PENDING')actions+='<button data-submission-action="APPROVE" data-partner="true" data-id="'+r.id+'">Accept switch</button><button data-submission-action="DENY" data-partner="true" data-id="'+r.id+'">Decline switch</button>';
  if(management&&kind){if(!kind||r.partner_status==='APPROVED')actions+='<button class="primary" data-submission-action="APPROVE" data-id="'+r.id+'">'+(kind?'Approve switch':'Approve & add '+Number(p.hours).toFixed(2)+' hours')+'</button>';actions+='<button data-submission-action="DENY" data-id="'+r.id+'">Deny</button>';}
  if(r.user_id===user.id)actions+='<button data-submission-action="CANCEL" data-id="'+r.id+'">Cancel request</button>';
 }
 if(kind&&r.status==='APPROVED'&&['WAITING_SCHEDULE','NEEDS_REVIEW'].includes(status)&&(management||r.user_id===user.id))actions+='<button data-submission-action="CANCEL" data-id="'+r.id+'">Cancel approved switch</button>';
 return '<div class="manage-card"><b>'+esc(kind?'Future switch · '+r.requester_name+' ↔ '+r.partner_name:'Missing hours · '+r.requester_name)+'</b><p>W-E '+date(p.week)+(kind?'<br>'+requestShift(p.from,p.week)+' ↔ '+requestShift(p.to,p.week):' · '+date(p.workDate)+(p.startTime?' · '+esc(p.startTime)+'–'+esc(p.endTime)+(p.overnight?' (next day)':''):'')+' · '+Number(p.hours).toFixed(2)+' hours')+'</p><p>'+esc(p.note)+'</p><p class="request-status">'+esc(labels[status]||status)+(kind?' · Other guard: '+esc(r.partner_status):'')+'</p>'+(r.detail?'<p>'+esc(r.detail)+'</p>':'')+(r.decision_note?'<p>Manager: '+esc(r.decision_note)+'</p>':'')+(!kind&&management&&r.status==='PENDING'?'<p class="muted">Check existing hours before approving. This adds an adjustment to payable hours; schedule and billable hours stay unchanged.</p>':'')+(!kind?'<p>Recorded paid: '+Number((r.payments||[]).reduce((n,x)=>n+x.hours,0)).toFixed(2)+' hours'+(r.status==='APPROVED'?' · Still owed: '+Math.max(0,p.hours-(r.payments||[]).reduce((n,x)=>n+x.hours,0)).toFixed(2)+' hours':'')+'</p>':'')+'<div class="toolbar">'+actions+'</div></div>';
 }).join('');}
function wireSubmissions(container,management=false){container.querySelectorAll('[data-submission-action]').forEach(button=>button.onclick=()=>run(async()=>{
 await savesFinished();await api('/api/submissions/'+button.dataset.id,{method:'PATCH',body:JSON.stringify({action:button.dataset.submissionAction,partnerResponse:button.dataset.partner==='true',note:management?(prompt('Decision note (optional):')||''):''})});if(management)location.reload();else await loadGuard();
 },management?'managementStatus':'requestError'));}

function vacationChoiceOptions(items){return '<option value="">Choose saved vacation</option>'+items.map(v=>'<option value="'+esc(v.id)+'">'+date(v.from)+' through '+date(v.to)+'</option>').join('');}
function renderVacationChoices(){const selected=$('moveVacationChoice').value;$('moveVacationChoice').innerHTML=vacationChoiceOptions(guardVacations);if(guardVacations.some(v=>v.id===selected))$('moveVacationChoice').value=selected;$('moveVacationCurrent').textContent=guardVacations.length?'All your saved vacation dates are available above.':'No saved vacations found for your schedule name.';updateVacationMoveDates();}
function updateVacationMoveDates(){const v=guardVacations.find(v=>v.id===$('moveVacationChoice').value);$('moveVacationTo').value='';if(v&&$('moveVacationFrom').value){try{$('moveVacationTo').value=vacationMoveEnd($('moveVacationFrom').value,v);}catch{}}}
$('moveVacationChoice').onchange=$('moveVacationFrom').onchange=updateVacationMoveDates;
function vacationMoveCards(items,management=false){return items.map(r=>{const p=r.payload,buttons=r.status!=='PENDING'?'':(management?'<button class="primary" data-vacation-action="APPROVE" data-id="'+r.id+'">Approve vacation move</button><button data-vacation-action="DENY" data-id="'+r.id+'">Deny</button>':r.user_id===user.id?'<button data-vacation-action="CANCEL" data-id="'+r.id+'">Cancel request</button>':'');return '<div class="manage-card"><b>Vacation move · '+esc(p.guard)+'</b><p>Current: '+date(p.from)+' through '+date(p.to)+'<br>Requested: '+date(p.newFrom)+' through '+date(p.newTo)+'</p><p>'+esc(p.note)+'</p><p class="request-status">'+esc({PENDING:'Waiting for manager approval',APPROVED:'Approved — vacation moved',DENIED:'Denied — current vacation kept',CANCELLED:'Cancelled — current vacation kept'}[r.status]||r.status)+'</p>'+(r.decision_note?'<p>Manager: '+esc(r.decision_note)+'</p>':'')+'<div class="toolbar">'+buttons+'</div></div>';}).join('');}
function wireVacationMoves(container,management=false){container.querySelectorAll('[data-vacation-action]').forEach(button=>button.onclick=()=>run(async()=>{await savesFinished();await api('/api/vacation-moves/'+button.dataset.id,{method:'PATCH',body:JSON.stringify({action:button.dataset.vacationAction,note:management?(prompt('Decision note (optional):')||''):''})});if(management)location.reload();else await loadGuard();},management?'managementStatus':'requestError'));}
async function manualVacationMovePanel(){
 await savesFinished();const w=window.scheduleApp.getWorkspace(),names=[...new Set([...w.staff,...(w.temporaryStaff||[]),...(w.vacations||[]).map(v=>v.guard),...Object.values(w.weeks).flatMap(s=>(s.events||[]).filter(e=>e.type==='Vacation').map(e=>e.guard))])].sort();let choices=[];
 panel('Move vacation manually','<form id="manualVacationForm"><label>Guard<select id="manualVacationGuard"><option value="">Choose guard</option>'+names.map(n=>'<option>'+esc(n)+'</option>').join('')+'</select></label><label>Current vacation<select id="manualVacationChoice"></select></label><div class="subfields"><label>New first day off<input id="manualVacationFrom" type="date" required></label><label>New last day off<input id="manualVacationTo" type="date" readonly></label></div><label>Reason<input id="manualVacationNote" maxlength="250" required></label><p class="muted">Moves the same number of vacation days. Review any existing coverage before moving the vacation.</p><button class="primary">Move vacation now</button></form>');
 const dates=()=>{const v=choices.find(v=>v.id===$('manualVacationChoice').value);$('manualVacationTo').value='';if(v&&$('manualVacationFrom').value)try{$('manualVacationTo').value=vacationMoveEnd($('manualVacationFrom').value,v);}catch{}};
 $('manualVacationGuard').onchange=()=>run(async()=>{choices=[];$('manualVacationChoice').innerHTML=vacationChoiceOptions([]);if(!$('manualVacationGuard').value)return;const result=await api('/api/my-vacations?guard='+encodeURIComponent($('manualVacationGuard').value));choices=result.vacations;$('manualVacationChoice').innerHTML=vacationChoiceOptions(choices);dates();});$('manualVacationChoice').onchange=$('manualVacationFrom').onchange=dates;
 $('manualVacationForm').onsubmit=e=>{e.preventDefault();run(async()=>{await savesFinished();const v=choices.find(v=>v.id===$('manualVacationChoice').value);if(!v)throw Error('Choose a saved vacation.');await api('/api/vacation-moves/manual',{method:'POST',body:JSON.stringify({guard:$('manualVacationGuard').value,vacationId:v.id,signature:v.signature,newFrom:$('manualVacationFrom').value,note:$('manualVacationNote').value,revision:window.__BOOT.revision})});location.reload();});};
}

$('missingStartTime').oninput=$('missingEndTime').oninput=async()=>{const {missingInterval}=await import('./people-model.js');try{const v=missingInterval($('missingStartTime').value,$('missingEndTime').value);$('missingHoursAmount').value=Number(v.hours.toFixed(4));$('missingTimeNote').textContent=v.overnight?'Ends the following day.':'';}catch(e){$('missingHoursAmount').value='';$('missingTimeNote').textContent=e.message;}};
